from tools.mcptester.mcptester.scenarios.base import BaseScenario, TestCase

class CommandsScenario(BaseScenario):
    name = 'commands'
    description = 'Investigation command tools (investigate, feedback, ask)'

    def get_test_cases(self) -> list[TestCase]:
        return [TestCase(name='investigate_simple', tool='investigate_error', params={'error_message': 'Timeout waiting for data from BoardReader'}, expected={'contains_keys': ['investigation_id', 'outcome'], 'error': False, 'value_in': {'outcome': ['CONFIDENT', 'PROBABLE', 'UNCERTAIN', 'CONTRADICTORY', 'INSUFFICIENT']}}, description='Simple investigation with just error message'), TestCase(name='investigate_with_context', tool='investigate_error', params={'error_message': 'Connection refused', 'log_content': '2024-01-15 10:00:00 INFO Starting\n2024-01-15 10:01:00 ERROR Connection refused', 'context_lines': 30}, expected={'contains_keys': ['investigation_id', 'outcome'], 'error': False}, description='Investigation with log context'), TestCase(name='investigate_with_error_line', tool='investigate_error', params={'error_message': 'Buffer overflow', 'log_content': 'Line 1\nLine 2 ERROR\nLine 3', 'error_line': 2}, expected={'contains_keys': ['investigation_id'], 'error': False}, description='Investigation targeting specific error line'), TestCase(name='investigate_empty_message', tool='investigate_error', params={'error_message': ''}, expected={'json_valid': True}, description='Investigation with empty message (edge case)'), TestCase(name='analyze_message_simple', tool='analyze_message', params={'message': 'Fragment timeout in DataTransfer'}, expected={'contains_keys': ['investigation_id', 'outcome'], 'error': False}, description='Lightweight message analysis'), TestCase(name='analyze_message_complex', tool='analyze_message', params={'message': 'Error: SharedMemoryManager failed to allocate 1GB buffer'}, expected={'contains_keys': ['investigation_id'], 'error': False}, description='Analysis of complex error message'), TestCase(name='feedback_correct', tool='submit_feedback', params={'investigation_id': 'inv_test001', 'correct': True}, expected={'contains_keys': ['success'], 'error': False, 'exact_values': {'success': True}}, description='Submit positive feedback'), TestCase(name='feedback_incorrect_with_cause', tool='submit_feedback', params={'investigation_id': 'inv_test001', 'correct': False, 'actual_cause': 'Race condition in buffer management'}, expected={'contains_keys': ['success'], 'error': False}, description='Submit negative feedback with actual cause'), TestCase(name='feedback_invalid_id', tool='submit_feedback', params={'investigation_id': 'invalid_12345', 'correct': True}, expected={'contains_keys': ['error']}, description='Feedback for non-existent investigation'), TestCase(name='feedback_incorrect_no_cause', tool='submit_feedback', params={'investigation_id': 'inv_test001', 'correct': False}, expected={'contains_keys': ['success'], 'error': False}, description='Submit negative feedback without cause'), TestCase(name='ask_simple_question', tool='ask_experts', params={'question': 'What is a BoardReader in artdaq?'}, expected={'contains_keys': ['answer', 'confidence'], 'error': False}, description='Simple question to expert panel'), TestCase(name='ask_with_context', tool='ask_experts', params={'question': 'Why might this error occur?', 'log_content': '2024-01-15 10:00:00 ERROR Timeout in FragmentGenerator'}, expected={'contains_keys': ['answer'], 'error': False}, description='Question with log context'), TestCase(name='ask_troubleshooting', tool='ask_experts', params={'question': 'How do I debug SharedMemoryManager issues?'}, expected={'contains_keys': ['answer', 'confidence'], 'error': False}, description='Troubleshooting question'), TestCase(name='ask_best_practice', tool='ask_experts', params={'question': 'What are best practices for configuring fragment timeouts?'}, expected={'contains_keys': ['answer'], 'error': False}, description='Best practice question')]